SELECT
  COALESCE(CONVERT(VARCHAR(40), CAST([id] AS BIGINT)), '<NULL>') AS k0,
  LOWER(CONVERT(VARCHAR(32), HASHBYTES('MD5', CONCAT(CAST(COALESCE(RTRIM([code]), '<NULL>') AS VARCHAR(MAX)), '|~|', COALESCE(RTRIM([name]), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(60), CAST([amount] AS DECIMAL(38,6))), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(60), CAST([ratio] AS DECIMAL(38,6))), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(40), CAST([units] AS BIGINT)), '<NULL>'), '|~|', COALESCE(CASE WHEN [is_active] IS NULL THEN NULL WHEN [is_active] = 1 THEN '1' ELSE '0' END, '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(10), [born_on], 23), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(26), CAST([updated_at] AS DATETIME2(6)), 121), '<NULL>'))), 2)) AS row_hash
FROM [dq].[customers]
WHERE (load_dt = '2026-01-01')
